// @ai:generated by=claude-opus-4-6 date=2026-02-27
package contract

// @ai purpose: RunConfig 執行引擎設定 — 集中管理 TestAll / ObserveAll / Observe 的並行、重試、速率限制與 FailFast 策略
// @ai input: 無（僅定義型別與工具函式，由 TestAll / runObserve 呼叫）
// @ai output: RunConfig 型別、mergeRunConfig() 正規化函式
// @ai sideeffect: 無
// date: 2026-05-23

import (
	"runtime"
	"strings"
	"time"

	"github.com/maoxiaoyue/hypgo/pkg/schema"
)

// RunConfig 控制 TestAll / ObserveAll / Observe 的執行策略
//
// 零值等同於原有行為（循序、不重試、不限速、不 FailFast），保持向後相容。
//
// 使用範例：
//
//	contract.TestAll(t, r, contract.RunConfig{
//	    Parallel:   true,
//	    MaxWorkers: 4,
//	    RetryCount: 2,
//	    RetryDelay: 500 * time.Millisecond,
//	    RateLimit:  10,
//	    FailFast:   false,
//	})
type RunConfig struct {
	// Parallel 啟用並行執行
	// TestAll 使用 t.Parallel()，ObserveAll/Observe 使用 goroutine pool
	Parallel bool

	// MaxWorkers 限制同時執行的路由數（TestAll 的子測試與 Observe 的 goroutine 皆適用；
	// TestAll 另受 go test -parallel 限制，取兩者較小者）
	// 0 或負值 → 自動設為 runtime.GOMAXPROCS(0)
	MaxWorkers int

	// RetryCount 失敗後的額外重試次數（0 = 不重試）
	// 例如 RetryCount=2 表示最多執行 3 次（1 次初始 + 2 次重試）
	RetryCount int

	// RetryDelay 每次重試前的等待時間（0 = 立即重試）
	RetryDelay time.Duration

	// RateLimit 每秒最大執行數（0 = 不限制）
	// 使用 time.Ticker 實作，多個 goroutine 競爭接收，天然 goroutine-safe
	RateLimit int

	// FailFast 第一個失敗後立即停止後續測試
	// 並行模式下：已啟動的 goroutine 會繼續完成，新的不再啟動
	FailFast bool

	// Headers 每個自動產生的請求都帶上的標頭，例如需要授權的路由：
	//
	//	contract.TestAll(t, r, contract.RunConfig{Headers: map[string]string{"Authorization": "Bearer " + token}})
	//
	// 先前無法帶標頭，掛了 JWT 的路由在 TestAll 一律 401
	Headers map[string]string

	// Params 路徑參數的值（鍵為參數名稱，不含冒號）：{"id": "42"} 讓 /users/:id 打 /users/42。
	// 沒列的參數依名稱猜（:id → 1）；測試資料的 id 不是 1 時用它指定
	Params map[string]string

	// Skip 不自動測試的路由（TestAll 以 t.Skip 標示，Observe 不列入）。每一項是
	// "METHOD /path"、只寫路徑（所有方法），或以 * 結尾的前綴（"/admin/*"、"DELETE /api/*"）；
	// 路徑用註冊時的樣式（"/users/:id"）。這些路由另以 contract.Test 個別撰寫
	Skip []string

	// RecordHistory 將每次測試結果 append 到 .hyp/eval_history.jsonl
	// true 時自動記錄（含路由、狀態、執行次數、延遲、git commit、輸入 hash），寫入失敗時測試失敗。
	// TestAll 不能掛 Graders（自動產生的輸入評不出品質）；要記錄評分請用 Test 與 TestCase.RecordHistory
	// false 時不記錄（零值，向後相容）
	RecordHistory bool
}

// mergeRunConfig 取第一個 RunConfig 或回傳零值，並正規化 MaxWorkers
//
// @ai purpose: 讓 TestAll(t, r) 零引數呼叫繼續向後相容，並確保 MaxWorkers 非零
// @ai input: []RunConfig（可為空或 nil）
// @ai output: 單一正規化的 RunConfig
// @ai sideeffect: 無
// date: 2026-05-23
func mergeRunConfig(cfgs []RunConfig) RunConfig {
	var cfg RunConfig
	if len(cfgs) > 0 {
		cfg = cfgs[0]
	}
	if cfg.MaxWorkers <= 0 {
		cfg.MaxWorkers = runtime.GOMAXPROCS(0)
	}
	if cfg.RetryCount < 0 {
		cfg.RetryCount = 0 // 先前負數讓重試迴圈一次都不跑，每條路由以空的原因失敗
	}
	return cfg
}

// skips 回報 route 是否在 Skip 清單內
func (cfg RunConfig) skips(route schema.Route) bool {
	full := route.Method + " " + route.Path
	for _, pat := range cfg.Skip {
		pat = strings.TrimSpace(pat)
		if prefix, ok := strings.CutSuffix(pat, "*"); ok {
			if strings.HasPrefix(full, prefix) || strings.HasPrefix(route.Path, prefix) {
				return true
			}
		} else if pat == full || pat == route.Path {
			return true
		}
	}
	return false
}

// testCase 依 schema 產生這條路由的測試案例，套上 Headers / Params
func (cfg RunConfig) testCase(route schema.Route) TestCase {
	tc := generateTestCase(route, cfg.Params)
	tc.Headers = cfg.Headers
	tc.schemaRoute = &route
	tc.generated = true
	return tc
}
